const insc = $('Normalizar inscripción').first().json;
if (!insc.id_evento || !insc.email) throw new Error('event_and_email_required');
const id = insc.id_evento + ':' + String(insc.email).trim().toLowerCase();
const codigo = insc.id_evento + '-' + Math.random().toString(36).slice(2, 10).toUpperCase();
return [{ json: { ...insc, id, codigo, qr_url:'https://api.qrserver.com/v1/create-qr-code/?size=300x300&data='+encodeURIComponent(codigo), asistio:false } }];
